$db=new Database($config);$orders=new CommerceOrders($db,$config,$root);$invoices=$orders->invoices;$checks=0;
function check(bool $ok,string $why):void{global $checks;if(!$ok)throw new RuntimeException($why);$checks++;}
function rejects(callable $fn,string $why):void{try{$fn();}catch(Throwable $e){check(true,$why);return;}throw new RuntimeException($why);}
function input(array $extra=[]):array{return array_replace(['accept_terms'=>true,'accept_privacy'=>true,'legal_version'=>CommerceLegal::VERSION,'edition'=>'content','term'=>'annual','domain'=>'invoice.example.test','modules'=>[],'services'=>[],'operation_id'=>bin2hex(random_bytes(16))],$extra);}
