function fakeAccount(string $prefix,string $bik,bool $correspondent=false):string{for($n=0;$n<10;$n++){$account=substr_replace($prefix,(string)$n,8,1);$digits=($correspondent?'0'.substr($bik,4,2):substr($bik,-3)).$account;$sum=0;foreach(str_split($digits)as $i=>$digit)$sum+=(int)$digit*[7,1,3][$i%3];if($sum%10===0)return $account;}throw new RuntimeException('QA checksum');}
