$before=$invoices->latest($id)['seller_cipher'];$invoices->bank->save(['bank'=>'Другое тестовое название']);check($before===$invoices->latest($id)['seller_cipher'],'old beneficiary snapshot immutable');
$p=proof($o);foreach([['amount'=>'1.00'],['amount'=>'7901.00'],['confirmed'=>false],['paid_on'=>'2099-01-01'],['source'=>'invented'],['invoice_id'=>0]]as $bad)rejects(fn()=>$invoices->confirm($id,$owner,array_replace($p,$bad)),'invalid confirmation rejected');
check($orders->view($id)['payment_state']==='pending','bad proof cannot mark paid');
