$delivery=$db->one('SELECT * FROM byp_customer_deliveries WHERE order_id=?',[$id]);$link=$db->one('SELECT l.* FROM byp_license_registry l JOIN byp_license_order_links k ON k.license_id=l.id WHERE k.order_id=?',[$id]);check($link['status']==='active'&&$link['purchase_price']==='7900.00','bank proof issues real active licence at licence price');
$invoices->confirm($id,$owner,$p);$invoices->confirm($id,$owner,array_replace($p,['operation_id'=>bin2hex(random_bytes(16))]));check((int)$db->one('SELECT COUNT(*) n FROM byp_commerce_manual_payments WHERE order_id=?',[$id])['n']===1,'double click and new token cannot duplicate payment');check((int)$db->one('SELECT COUNT(*) n FROM byp_license_order_links WHERE order_id=?',[$id])['n']===1,'double confirm cannot duplicate licence');
rejects(fn()=>$invoices->confirm($id,$owner,array_replace($p,['reference'=>'different'])),'changed repeat rejected');
rejects(fn()=>$invoices->cancel($id,(int)$inv['id'],'Не отменять оплаченный счёт'),'paid invoice cannot cancel');
$zip=new ZipArchive();check($zip->open($delivery['archive_path'])===true,'buyer ZIP exists');check(!json_decode($zip->getFromName('site/build-manifest.json'),true)['test_purchase'],'manual payment ZIP has production manifest');for($n=0;$n<$zip->numFiles;$n++){check(!preg_match('~^site/(?:_storage|_private|owner|account|commerce)(?:/|$)~',$zip->getNameIndex($n)),'ZIP has no private runtime');}check(!str_contains($zip->getFromName('site/build-manifest.json'),$bank['account']),'manifest has no beneficiary');$zip->close();
$other=$orders->create($buyer,input(['domain'=>'other-invoice.test']));rejects(fn()=>$invoices->confirm((int)$other['id'],$owner,array_replace($p,['invoice_id'=>$other['invoice']['id'],'operation_id'=>bin2hex(random_bytes(16))])),'same bank transfer cannot pay second order');
$invoices->cancel((int)$other['id'],(int)$other['invoice']['id'],'Согласован другой состав');$invoices->cancel((int)$other['id'],(int)$other['invoice']['id'],'Повтор отмены счета');rejects(fn()=>$invoices->confirm((int)$other['id'],$owner,proof($other)),'canceled invoice cannot confirm');
$issue=['operation_id'=>bin2hex(random_bytes(16)),'scope'=>'Тестовая лицензия. Архив и ключ передаются в течение рабочего дня после оплаты.'];$new=$invoices->issue((int)$other['id'],$owner,$issue);check($new['id']!==$other['invoice']['id']&&!$new['accepted_at'],'reissue requires new acceptance');rejects(fn()=>$invoices->issue((int)$other['id'],$owner,array_replace($issue,['scope'=>'Другой состав услуги и иной срок передачи результата.'])),'operation cannot change invoice');
$input=input(['invoice_id'=>$new['id']]);$invoices->accept((int)$other['id'],$buyer,$input);rejects(fn()=>$invoices->accept((int)$other['id'],$buyer,input(['invoice_id'=>$other['invoice']['id']])),'old invoice acceptance rejected');
$db->execute('UPDATE byp_commerce_invoices SET expires_on="2020-01-01" WHERE id=?',[$new['id']]);rejects(fn()=>$invoices->confirm((int)$other['id'],$owner,proof($orders->view((int)$other['id']))),'expired invoice blocked');
$service=$orders->create($buyer,input(['services_only'=>true,'services'=>['launch'],'domain'=>'']));check($service['edition']==='services'&&$service['amount_minor']==0&&!$service['invoice'],'services alone never charge unwanted licence');
$serviceId=(int)$service['id'];$issue=['operation_id'=>bin2hex(random_bytes(16)),'scope'=>'Запуск тестового сайта: настройка, передача инструкции в течение 5 рабочих дней после оплаты; приёмка по проверке главной страницы.','service_prices'=>['launch'=>'25000.00']];$i=$invoices->issue($serviceId,$owner,$issue);check(!$i['accepted_at']&&(int)$i['amount_minor']===2500000,'service exact quote requires acceptance');rejects(fn()=>$invoices->confirm($serviceId,$owner,proof($orders->view($serviceId))),'unaccepted service invoice cannot confirm');$invoices->accept($serviceId,$buyer,input(['invoice_id'=>$i['id']]));$paid=$invoices->confirm($serviceId,$owner,proof($orders->view($serviceId)));check($paid['kind']==='service'&&$paid['fulfillment_state']==='not_needed'&&!$paid['purchase_url'],'service payment does not issue CMS licence or claim completion');
$mixed=$orders->create($buyer,input(['services'=>['launch']]));$mixedId=(int)$mixed['id'];$i=$invoices->issue($mixedId,$owner,array_replace($issue,['operation_id'=>bin2hex(random_bytes(16))]));$invoices->accept($mixedId,$buyer,input(['invoice_id'=>$i['id']]));$invoices->confirm($mixedId,$owner,proof($orders->view($mixedId)));$license=$db->one('SELECT l.* FROM byp_license_registry l JOIN byp_license_order_links k ON k.license_id=l.id WHERE k.order_id=?',[$mixedId]);check($license['purchase_price']==='7900.00','service amount never inflates licence registry price');
$refunds=new CommerceRefunds($db,$config,$orders);$r=['operation_id'=>bin2hex(random_bytes(16)),'amount'=>'7900.00','license_action'=>'revoke','reason'=>'Согласован полный возврат тестовой покупки','reference'=>'QA-refund-'.bin2hex(random_bytes(8)),'paid_on'=>gmdate('Y-m-d'),'confirmed'=>true];rejects(fn()=>$refunds->recordManual($id,$owner,array_replace($r,['license_action'=>'keep'])),'full refund cannot retain rights');$refunds->recordManual($id,$owner,$r);$refunds->recordManual($id,$owner,$r);check($orders->view($id)['fulfillment_state']==='refunded'&&!$orders->view($id)['purchase_url'],'recorded full refund blocks downloads');check($db->one('SELECT status FROM byp_license_registry WHERE id=?',[$link['id']])['status']==='suspended','confirmed refund revokes licence');check($db->one('SELECT refund_state FROM byp_commerce_receipts WHERE order_id=?',[$id])['refund_state']==='required','NPD refund correction is required');
$renewal=$orders->create($buyer,input(['renewal_license_id'=>$license['id']]));$renewId=(int)$renewal['id'];$oldUntil=$license['valid_until'];$renewProof=proof($renewal);$invoices->confirm($renewId,$owner,$renewProof);$after=$db->one('SELECT valid_until FROM byp_license_registry WHERE id=?',[$license['id']])['valid_until'];$invoices->confirm($renewId,$owner,$renewProof);check($after>$oldUntil&&$db->one('SELECT valid_until FROM byp_license_registry WHERE id=?',[$license['id']])['valid_until']===$after,'bank renewal grants exactly one year once');
$refunds->recordManual($renewId,$owner,array_replace($r,['operation_id'=>bin2hex(random_bytes(16)),'reference'=>'QA-renew-refund-'.bin2hex(random_bytes(5))]));check($db->one('SELECT valid_until FROM byp_license_registry WHERE id=?',[$license['id']])['valid_until']===$oldUntil,'bank renewal refund removes only its period');
$retry=$orders->create($buyer,input(['domain'=>'retry-invoice.test']));$retryId=(int)$retry['id'];$db->execute('UPDATE byp_customer_orders SET domain="invalid domain" WHERE id=?',[$retryId]);rejects(fn()=>$invoices->confirm($retryId,$owner,proof($retry)),'delivery fault after payment reported');check($orders->view($retryId)['payment_state']==='paid'&&$orders->view($retryId)['fulfillment_state']==='failed','delivery error preserves confirmed money');$db->execute('UPDATE byp_customer_orders SET domain="retry-invoice.test" WHERE id=?',[$retryId]);$orders->fulfill($retryId);check($orders->view($retryId)['fulfillment_state']==='ready','delivery retry recovers without another payment');
