file_put_contents(dirname($root).'/invoice-result.json',json_encode(['bank_settings'=>$bank,'email'=>$db->one('SELECT email FROM byp_customer_accounts WHERE id=?',[$buyer])['email'],'order_id'=>$mixedId,'buyer_id'=>$buyer,'invoice_id'=>$i['id'],'service_order'=>$serviceId,'checks'=>$checks],JSON_PRETTY_PRINT));
